INSERT INTO products(name, category_id, description, price, discount_price, image_url, created_at, updated_at)
SELECT s.name, c.category_id, s.description, s.price::numeric, s.discount_price::numeric,
       s.image_url, s.created_at::timestamptz, s.updated_at::timestamptz
FROM seed s JOIN categories c ON c.name = s.category_name
WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.name = s.name);
